<script setup lang="ts">
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowRight, CalendarDays, ShieldCheck, Sprout, Eye, EyeOff } from 'lucide-vue-next'
import { useAuth } from '../stores/auth'

const auth = useAuth(), router = useRouter(), route = useRoute()
const username = ref(''), password = ref(''), visible = ref(false), busy = ref(false), error = ref('')
async function submit() { busy.value = true; error.value = ''; try { await auth.login(username.value.trim(), password.value); password.value = ''; const target = typeof route.query.redirect === 'string' && route.query.redirect.startsWith('/') && !route.query.redirect.startsWith('//') && !route.query.redirect.startsWith('/login') ? route.query.redirect : '/'; await router.replace(target) } catch (e) { error.value = e instanceof Error ? e.message : '登录失败，请重试。' } finally { busy.value = false } }
</script>
<template><div class="login-page"><section class="login-story"><a class="brand" href="/"><span class="brand-mark">课</span><span>课序<small>COURSE STUDIO</small></span></a><div class="login-story-content"><p class="eyebrow">A LITTLE ORDER. A LOT OF POSSIBILITY.</p><h1>选择热爱，<br>让成长井然有序。</h1><p>从第一门心仪的课程，到每一次认真收获。<br>属于你的新学期，在这里慢慢展开。</p><div class="login-capabilities"><div class="login-capability"><span><CalendarDays :size="17"/></span><div><strong>课程与时间，好好安排</strong><small>清晰的课程信息与每周课表</small></div></div><div class="login-capability"><span><Sprout :size="17"/></span><div><strong>每一份努力，都有回响</strong><small>选课、教学与成绩的完整旅程</small></div></div><div class="login-capability"><span><ShieldCheck :size="17"/></span><div><strong>各有其职，一切有序</strong><small>学生、教师与教务的专属工作空间</small></div></div></div></div><p class="login-footer">COURSE STUDIO · THOUGHTFUL LEARNING, ORGANIZED.</p></section><main class="login-form-wrap"><div class="login-box"><p class="eyebrow">WELCOME BACK</p><h2>欢迎回到课序</h2><p class="login-description">登录你的账户，继续新学期的故事。</p><div v-if="route.query.expired" class="notice-banner notice-warning" role="status">本次登录已失效，请重新登录。已保存的教学数据不受影响。</div><div v-if="route.query.unavailable" class="notice-banner notice-warning" role="status">服务暂时无法连接，请确认服务启动后再次尝试。</div><div v-if="error" class="error-inline" role="alert">{{ error }}</div><form @submit.prevent="submit"><label class="field">账户<input v-model="username" name="username" autocomplete="username" placeholder="请输入账户名" maxlength="100" required autofocus :disabled="busy"></label><label class="field">密码<div class="password-field"><input v-model="password" name="password" :type="visible ? 'text' : 'password'" autocomplete="current-password" placeholder="请输入登录密码" required :disabled="busy"><button type="button" class="icon-button" :aria-label="visible ? '隐藏密码' : '显示密码'" @click="visible = !visible"><EyeOff v-if="visible" :size="17"/><Eye v-else :size="17"/></button></div></label><button class="button" type="submit" :disabled="busy">{{ busy ? '正在登录…' : '进入我的工作台' }}<ArrowRight :size="15"/></button></form><p class="login-help">账户由教务管理员分配。课堂演示使用部署时生成的专用账户与密码，详见本次部署的私有凭据说明；页面不会保存你的密码。</p><p class="login-meta">安心学习，认真选择。课序与你同行。</p></div></main></div></template>
